package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// worker 模拟一个耗时任务，通过 select 监听 ctx.Done() 实现「协作式取消」
func worker(ctx context.Context, id int, wg *sync.WaitGroup, results chan<- int) {
	defer wg.Done()

	// 不同 worker 模拟不同的处理耗时：1~5 号分别为 200ms / 400ms / 600ms / 800ms / 1000ms
	workTime := time.Duration(id*200) * time.Millisecond

	select {
	case <-time.After(workTime):
		results <- id
		fmt.Printf("worker-%d 完成（耗时 %v）\n", id, workTime)
	case <-ctx.Done():
		// ctx 被取消或超时，立刻收尾返回，避免 goroutine 泄漏
		fmt.Printf("worker-%d 中止：%v\n", id, ctx.Err())
	}
}

func main() {
	// 1. 派生一个 500ms 超时的 context（超时后自动触发取消）
	ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
	// 无论走哪个分支都必须调用 cancel，否则 ctx 内部的 timer 和引用链会泄漏
	defer cancel()

	results := make(chan int, 5) // 带缓冲，worker 写入不会阻塞
	var wg sync.WaitGroup

	// 2. 启动 5 个 worker，全部共享同一个 ctx
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go worker(ctx, i, &wg, results)
	}

	// 3. 等全部 worker 退出后再 close，主 goroutine 才能安全地 range
	go func() {
		wg.Wait()
		close(results)
	}()

	// 4. 收集成功完成的结果
	var done []int
	for r := range results {
		done = append(done, r)
	}
	fmt.Println("成功完成的 worker:", done)

	// 5. 用 errors.Is 判断错误类型（兼容被 %w 包装过的错误）
	switch {
	case errors.Is(ctx.Err(), context.DeadlineExceeded):
		fmt.Println("结束原因：触发了超时（DeadlineExceeded）")
	case errors.Is(ctx.Err(), context.Canceled):
		fmt.Println("结束原因：被主动取消（Canceled）")
	}

	// 6. 查看 context 的截止时间与剩余时间（常用于把 deadline 继续传给下游）
	if deadline, ok := ctx.Deadline(); ok {
		fmt.Printf("截止时间: %v, 剩余: %v\n",
			deadline.Format("15:04:05.000"), time.Until(deadline))
	}
}

