package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		time.Sleep(100 * time.Millisecond)
		cancel()
	}()

	select {
	case <-time.After(1 * time.Second):
		fmt.Println("超时")
	case <-ctx.Done():
		fmt.Println("取消:", ctx.Err())
	}
}
